    use crate::hir::funded::work as paid;
    const KEYS: &[(&str, StringOp)] = &[
        (take::ID, StringOp::Take),
        (LEN_ID, StringOp::Len),
        (CONCAT_ID, StringOp::Concat),
        (IS_EMPTY_ID, StringOp::IsEmpty),
        (STARTS_WITH_ID, StringOp::StartsWith),
        (CONTAINS_ID, StringOp::Contains),
