            same(&old_report[0], &report[0]);
            let output = actual.into_paid_report().ok().unwrap();
            assert_eq!(output.as_ptr(), backing.0);
            assert_eq!(output[0].message.as_ptr(), backing.1);
            same(&legacy.into_paid_report().ok().unwrap()[0], &output[0]);
            drop(output);
